// Workspace defines model for Workspace.
type Workspace struct {
	// DeletedAt When the workspace was deleted; absent while it is in use
	DeletedAt *time.Time `json:"deletedAt,omitempty"`

	// FirstWeekDays How many days of the first week of a year are in that year, which says which week is numbered 1 when weeks are written by number. 4 is ISO 8601 when weeks start on Monday, 1 the week of January 1 and 7 the first whole week. Queries do not use it. See .agents/design/architecture.md §10.2.
	FirstWeekDays FirstWeekDays `json:"firstWeekDays"`
	Id            string        `json:"id"`
	Name          string        `json:"name"`

	// PurgeAt When the hourly maintenance purges a deleted workspace, at the latest an hour after this
	PurgeAt *time.Time `json:"purgeAt,omitempty"`

	// Timezone Default query time zone
	Timezone string `json:"timezone"`

	// WeekStart ISO weekday that weeks start on, 1 Monday or 7 Sunday
	WeekStart int `json:"weekStart"`
}

// WorkspaceInput defines model for WorkspaceInput.
type WorkspaceInput struct {
	FirstWeekDays *int    `json:"firstWeekDays,omitempty"`
	Name          string  `json:"name"`
	Timezone      *string `json:"timezone,omitempty"`
	WeekStart     *int    `json:"weekStart,omitempty"`
}

